          '巴比伦的天文祭司夜里数星星，把黄道分成12份（十二星座沿用至今），把圆周定为360度，把时间定为60进制——因为60能被2、3、4、5、6整除，算分数最方便。这套系统经希腊、阿拉伯传到欧洲：一小时60分、一分钟60秒。你此刻看一眼时间，就是在与五千年前的巴比伦握手。',
          '不止时间。汉谟拉比时代的巴比伦书吏就会解二次方程，泥板上还留有勾股数表，比毕达哥拉斯早了一千多年；祭司的天文日志连续记录数百年，成为后来希腊天文学与历法制定者的底账。地中海的星空，长期是按巴比伦的表格运转的。',
