          '湖畔强国环伺，他们先当雇佣兵，再靠联姻与结盟积蓄实力。1428 年，特诺奇蒂特兰与特斯科科、特拉科潘结成「三方同盟」，几十年间反客为主，压服整个墨西哥谷地。严格说它不是领土帝国，而是一部贡赋机器：不派总督，只收贡品。',
