          '同年，天花随败退的西军入城，继位的新帝染疫而死；1521 年 5 月起围城七十五天，断水断粮，8 月 13 日城陷。湖城在战火与瘟疫中十室九空，科尔特斯下令夷平全城，把墨西哥城直接铺在废墟上。今天大教堂与地铁站下面，大神庙的残石仍叠在阿兹特克的地基上。',
