          '它与欧亚帝国最深的差别是不用文字行政：人口、田亩、仓廪、贡赋，一切都结在「奇普」上——棉绳与驼毛绳，以颜色、结型、位置编码。今天存世的奇普约六百件，学者仍在争论它们是账本还是兼有叙事。帝国的国库，是一柜子绳子。',
