      '1944 年，法国考古学家马勒雷在越南南部湄公河三角洲的俄厄遗址向下挖了不到两米，铲子底下同时出现了几种文明：罗马帝国安敦尼王朝的金币、印度的红玉髓饰珠、波斯的琉璃、汉式的铜镜。这里既不是罗马也不是天竺，而是湄公河三角洲上一个名叫扶南的古国港口。两千年前，东西方的水手都来到这片河口，却都不在此久留——他们把货物交给中间人。做中间人的，就是东南亚最早的一批国家。',
