          '前 149 年第三次布匿战争爆发。迦太基交出武器与战舰求和，罗马却坚持拆城迁民。被逼到绝境的全城居民熔掉神庙金属铸武器，奴隶一律获释参战，围城三年。前 146 年小西庇阿破城，巷战六天六夜；据古人的回忆录记载，满城哭喊声中，这位罗马将军默默念起特洛伊亡国的诗句。',
