          '更大的手笔是文字。世宗不忍百姓有话说不出口，1443 年创制、1446 年颁布二十八个字母的「训民正音」，让不识汉字的人也能拼写自己的语言。老臣崔万理上书死谏，说自古中国从未因方言另造文字，自创新字是与蒙古、女真为伍；世宗不为所动。谚文起初被士大夫轻视为「女人用的字」，却在民间扎了根——六百年后，它是韩国的官方文字，也被字体学界公认为最优雅的表音设计之一。',
