          '1597 年他被谗言革职下狱，日本水军趁虚全歼朝鲜舰队；朝廷重新起用他时，他手里只剩十三艘船。鸣梁海战，十三艘船借狭窄海峡与潮流，击退百余艘日舰——海战史上以寡敌众的极限案例。1598 年露梁海战，李舜臣中弹，临终嘱咐侄子：战事正急，不要宣布我死。同月丰臣秀吉已病死，日军撤退，战争结束。朝鲜续命三百年，代价是国土残破、人口锐减、国库为之一空。',
