          '复国之后是漫长的南进。占婆自 11 世纪起就与北方拉锯，1471 年黎圣宗攻破其都城阇槃，占婆从此一蹶不振；17 世纪起，阮主政权向湄公河三角洲持续移民拓殖，把原属真腊势力范围的沃土纳入版图，河口沼泽上的柴棍——后来的西贡——由此兴起。从红河两条窄谷到今天狭长的 S 形国土，越南的地理骨架，是八百年一寸一寸长出来的。',
