      '公元 1 世纪，一位佚名希腊水手在《红海环航记》里给同行指路：要买上好的象牙与犀角，就停泊在阿杜利斯——非洲之角的港口，统治它的国王住在高原上的阿克苏姆城。此后六百年，这个王国把象牙、黄金与香料换回地中海的玻璃器与橄榄油，把国王头像与希腊文刻上金币，又比罗马更早把基督教立为国教。撒哈拉以南非洲最早的铸币国、最早的基督教帝国，都姓阿克苏姆。',
