          '远征的代价是内讧：穆尔西里死于宫廷刺杀，王族自相残杀数代。前 16 世纪中叶，国王铁列平颁下敕令：确立长子继承，禁止王室私斗，重大案件须经贵族会议裁定——这份「王位继承法」被视为最早的宪制文献之一。血的经验逼出来的制度，比政治哲学早了一千年。',
