          '埃及援军赶到，赫梯军队渡河抢掠埃军营地、阵脚自乱，会战打成平手：赫梯保住叙利亚霸权，埃及止步北上。拉美西斯在神庙里把平局刻成大捷，穆瓦塔里把消耗战守成胜利——双方都输不起，也赢不动。这场数千辆战车对冲的大会战，至今仍是古代世界规模之最。',
