          '载具同样是工程学：双体独木舟以木板缝合船身，配蟹爪帆，载得动淡水、种薯、猪鸡与全家——他们带的不是探险队，是一整套可以重启社会的生态系统。考古学家在夏威夷与新西兰出土的猪骨、鼠骨与芋头花粉证明：每一次登陆，都是一次有备而来的移民。',
