          '生意做到多远？米诺斯式陶器出现在埃及、叙利亚、塞浦路斯、希腊本土乃至西西里；埃及高官雷赫米拉的陵墓壁画上，画着名为「凯夫季乌」的克里特使节捧着牛头形酒器前来进贡。出口的主力是橄榄油、葡萄酒与彩陶：巨大的陶缸成排立于库房，一缸可容上千升，港口的船把这些液体财富运往四方。',
