          '与轻盈的画风相对的，是彻底的沉默：约前 1800 年，克里特人发明了欧洲最早的文字「线形文字 A」，至今无人破译；费斯托斯宫出土的圆盘上压印着 241 个字符、45 种符号，像一枚史前的「活字印版」，同样无人能读。1952 年英国建筑师文特里斯破译了线形文字 B——但那是后来希腊语使用者的账本，记的是橄榄油、羊毛与劳力，不是米诺斯人的语言。',
