          '1863 年元旦《解放宣言》生效，宣布叛乱各州的奴隶获得自由身；同年 11 月，葛底斯堡战场上林肯把战争重新定义为「民有、民治、民享」的试验——半个多世纪后，孙中山把这三个短语引为三民主义的核心表述。1865 年第 13 修正案废除奴隶制，林肯却在胜利后的第五天遇刺身亡。',
          '然而解放不等于平等。重建期结束，南方各州用吉姆·克劳法重建隔离，1896 年最高法院以「隔离但平等」予以背书——宣言的支票再次延期。从法律上拆除这套体系，要到 1954 年布朗案与 1964 年民权法：从葛底斯堡到孟菲斯，中间隔了整整一个世纪。',
