          '约 1250—1300 年，波利尼西亚航海者乘双体独木舟抵达新西兰，凭星辰、涌浪与候鸟导航跨越大洋——这是人类永久定居的最后一块主要陆块。口传史诗至今记得那些祖先之舟的名字：塔伊努伊、特·阿拉瓦……他们给这片陆地取名叫奥特亚罗瓦，「长白云之乡」。',
